import React, { useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAudio } from '../../contexts/AudioContext';

const AudioPlayer: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { currentTrack, playLandingMusic, playGameMusic, isPlaying } = useAudio();
  const hasAttemptedAutoplayRef = useRef(false);
  
  // Asegurar parámetro de autoplay en cualquier ruta
  useEffect(() => {
    const searchParams = new URLSearchParams(location.search);
    const shouldAutoplay = searchParams.get('autoplay') === 'true';
    
    // Si estamos en una ruta sin autoplay, añadir el parámetro
    if (!shouldAutoplay) {
      const newUrl = location.pathname + (location.pathname.includes('?') ? '&' : '?') + 'autoplay=true' + location.hash;
      navigate(newUrl, { replace: true });
    }
  }, [location, navigate]);
  
  // Verificar parámetro de autoplay en la URL y reproducir música automáticamente
  useEffect(() => {
    if (!hasAttemptedAutoplayRef.current) {
      const searchParams = new URLSearchParams(location.search);
      const shouldAutoplay = searchParams.get('autoplay') === 'true';
      
      if (shouldAutoplay) {
        console.log('Detectado parámetro autoplay=true, intentando reproducción automática...');
        
        // Intentar reproducir automáticamente
        const attemptAutoplay = async () => {
          const landingRoutes = ['/', '/login', '/register'];
          if (landingRoutes.includes(location.pathname)) {
            await playLandingMusic();
          } else {
            await playGameMusic();
          }
        };
        
        attemptAutoplay().catch(err => {
          console.warn('Error en reproducción automática:', err);
        });
        
        // También intentar múltiples veces con retraso
        setTimeout(() => {
          if (!isPlaying) attemptAutoplay();
        }, 1000);
        
        setTimeout(() => {
          if (!isPlaying) attemptAutoplay();
        }, 3000);
        
        hasAttemptedAutoplayRef.current = true;
      }
    }
  }, [location.search, location.pathname, playLandingMusic, playGameMusic, isPlaying]);
  
  // Cambiar la música según la ruta
  useEffect(() => {
    // Rutas que deberían tener música de la landing page
    const landingRoutes = ['/', '/login', '/register'];
    
    const changeMusic = async () => {
      // Comprobar si estamos en la landing page o una ruta relacionada
      if (landingRoutes.includes(location.pathname)) {
        if (currentTrack !== 'landing') {
          await playLandingMusic();
        }
      } else {
        // Para cualquier otra ruta, reproducir la música del juego
        if (currentTrack !== 'game') {
          await playGameMusic();
        }
      }
    };
    
    changeMusic();
  }, [location.pathname, currentTrack, playLandingMusic, playGameMusic]);
  
  // Este componente no renderiza nada visible
  return null;
};

export default AudioPlayer;
